// Evolution Go webhook payload format (adjust if different)
// Common formats for button click webhooks:
// Format A: { event: 'messages.upsert', data: { message: { interactiveResponseMessage: { nativeFlowResponseMessage: { paramsJson: '{"id":"approve_123"}' } } } } }
// Format B: { event: 'messages.upsert', data: { key: {}, message: { interactiveResponseMessage: { nativeFlowResponseMessage: { ... } } } } }
// Format C: { event: 'action', instanceId: '...', data: { id: 'approve_123' } }

const body = $input.first().json;
let buttonId = '';
let fromNumber = '';

// Try to extract from various payload formats
if (body.data) {
  // Try interactiveResponseMessage (WhatsApp Business API)
  const msg = body.data.message || body.data;
  if (msg && msg.interactiveResponseMessage) {
    const nativeFlow = msg.interactiveResponseMessage.nativeFlowResponseMessage;
    if (nativeFlow && nativeFlow.paramsJson) {
      try {
        const params = JSON.parse(nativeFlow.paramsJson);
        buttonId = params.id || '';
      } catch(e) {}
    }
  }
  // Try direct id field
  if (!buttonId && body.data.id) {
    buttonId = body.data.id;
  }
  // Extract sender number
  if (body.data.key && body.data.key.remoteJid) {
    fromNumber = body.data.key.remoteJid.split('@')[0];
  }
}

// Fallback: check top-level fields
if (!buttonId && body.id) {
  buttonId = body.id;
}
if (!fromNumber && body.from) {
  fromNumber = body.from.split('@')[0];
}

// Parse button ID: approve_123 or reject_123
let action = '';
let postId = '';

if (buttonId) {
  const parts = buttonId.split('_');
  action = parts[0] || ''; // 'approve' or 'reject'
  postId = parts.slice(1).join('_'); // the rest is the post ID
}

return [{
  json: {
    raw_body: JSON.stringify(body),
    button_id: buttonId,
    action: action,
    post_id: postId,
    from_number: fromNumber,
    parsed: action && postId ? true : false
  }
}];

// Aprovar: update status to 'scheduled'
// scheduled_at = NOW() so next cron picks it up
const action = $input.first().json.action;
const postId = $input.first().json.post_id;

if (action === 'approve') {
  return [{ json: { action: 'approve', post_id: postId, status: 'scheduled' } }];
} else if (action === 'reject') {
  return [{ json: { action: 'reject', post_id: postId, status: 'deleted' } }];
} else {
  return [{ json: { action: 'unknown', post_id: postId } }];
}
